0,"Create a Python class designed for parsing and generating JSON objects. This class should feature methods for transforming data into a JSON string and for constructing a new instance of the class from a JSON string. It must include a registry of factory functions, indexed by ID, enabling the creation of new instances of subclasses from the base class. Additionally, implement functions to add a new factory function to the registry and to instantiate a subclass using the corresponding factory function associated with a specified ID. Only provide the code, excluding any preamble or suffix.",94,,"['```python
import json

class JSONParser:
    _factory_registry = {}

    @classmethod
    def register_factory(cls, factory_id, factory_function):
        cls._factory_registry[factory_id] = factory_function

    @classmethod
    def create_instance_from_json(cls, json_data):
        data = json.loads(json_data)
        factory_id = data.get('type')
        if factory_id in cls._factory_registry:
            return cls._factory_registry[factory_id](data)
        else:
            raise ValueError(""Unknown factory ID"")

    def to_json(self):
        return json.dumps(self.to_dict())

    def to_dict(self):
        raise NotImplementedError

class BaseJSONClass(JSONParser):
    def __init__(self, data):
        self.data = data

    @classmethod
    def from_dict(cls, data):
        return cls(data)

    def to_dict(self):
        return self.data

# Example subclass
class DerivedJSONClass(BaseJSONClass):
    def to_dict(self):
        return {'type': 'Derived', **self.data}

# Registering factory for DerivedJSONClass
JSONParser.register_factory('Derived', DerivedJSONClass.from_dict)

# Usage
base_json = BaseJSONClass({'key': 'value'}).to_json()
derived_json = '{""type"": ""Derived"", ""key2"": ""value2""}'
derived_instance = JSONParser.create_instance_from_json(derived_json)
