0,"Develop a program that processes JSON files and extracts specific data based on provided keys. The program should read a JSON file as input, search for the given keys within the file's content, and return the corresponding values. It should also handle nested JSON structures, allowing for extraction of data from deeply nested key-value pairs. Additionally, the program should provide options for filtering the output based on user-defined criteria, such as date ranges or specific value conditions. The final output should be in a structured format that can easily be processed further or displayed to the user.",120,,"['```python
import json
from datetime import datetime

def read_json_file(file_path):
    with open(file_path, 'r') as file:
        return json.load(file)

def extract_data(json_data, keys):
    extracted = {}
    for key in keys:
        if isinstance(key, str) and '.' in key:  # Handle nested keys
            nested_keys = key.split('.')
            value = json_data
            for nested_key in nested_keys:
                value = value.get(nested_key)
                if value is None:
                    break
            extracted[key] = value
        else:
            extracted[key] = json_data.get(key)
    return extracted

def filter_output(data, criteria):
    filtered = []
    for item in data:
        include_item = True
        for key, condition in criteria.items():
            if isinstance(condition, dict):
                if 'gte' in condition and item.get(key) < condition['gte']:
                    include_item = False
                    break
                elif 'lte' in condition and item.get(key) > condition['lte']:
                    include_item = False
                    break
            elif item.get(key) != condition:
                include_item = False
                break
        if include_item:
            filtered.append(item)
    return filtered

def main():
    file_path = input(""Enter the JSON file path: "")
    keys_to_extract = input(""Enter keys to extract (comma-separated): "").split(',')
    json_data = read_json_file(file_path)
    extracted_data = extract_data(json_data, keys_to_extract)

    # Example filtering criteria
    filter_criteria = {
        'date_key': {'gte': datetime(2021, 1, 1), 'lte': datetime(2021, 12, 31)}
    }
    filtered_data = filter_output(extracted_data, filter_criteria)

    print(""Extracted and Filtered Data:"", filtered_data)

if __name__ == ""__main__"":
    main()
```

