    if len(password) < min_length:
        return False
    if sum(c.isupper() for c in password) < min_upper:
        return False
    if sum(c.islower() for c in password) < min_lower:
        return False
    if sum(c.isdigit() for c in password) < min_digits:
        return False
    special_chars = string.punctuation
    if sum(c in special_chars for c in password) < min_special:
        return False
    return True

