import hashlib

def sort_and_hash_file(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = sorted(file.readlines())

        sequence_number = int(lines[-1].strip())
        md5_hash = hashlib.md5()

        for line in lines:
            md5_hash.update(line.encode('utf-8'))

        return md5.hexdigest(), sequence_number

    except FileNotFoundError:
        return ""Error: File not found."", None
