1,Create a Python function that accepts a list of email addresses and sends them individual emails with personalized content using the smtplib library. The function should return a dictionary mapping each email address to the corresponding status of the sent email (success or failure).,95,,"['```python
import smtplib
from email.mime.text import MIMEText

def send_emails(email_list, sender_email, sender_password):
    smtp_server = 'smtp.gmail.com'
    smtp_port = 587
    email_status = {}

    try:
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(sender_email, sender_password)

        for email in email_list:
            msg = MIMEText(f""Hello! This is a personalized message for {email}."")
            msg['Subject'] = 'Personalized Email'
            msg['From'] = sender_email
            msg['To'] = email

            try:
                server.sendmail(sender_email, [email], msg.as_string())
                email_status[email] = 'success'
            except Exception as e:
                email_status[email] = str(e)

        server.quit()
    except Exception as e:
        return {email: str(e) for email in email_list}

    return email_status
```']",75,[0],[],True,0,0,0,

