import csv
import json
import hashlib

def compute_file_md5(file_path):
    with open(file_path, 'rb') as file:
        md5_hash = hashlib.md5()
        while chunk := file.read(8192):
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

def extract_sequence_number_from_sorted_file(file_path):
    sequence_numbers = []
    with open(file_path, 'r') as file:
        for line in reversed(list(file)):
            if line.strip():
                sequence_numbers.append(int(line.strip()))
                break
    return sequence_numbers

def process_data(input_csv, output_json, processing_rules):
    input_hash = compute_file_md5(input_csv)

    if input_hash == ""NOT FOUND"":
        print(""Error: File not found or empty."")
        return

    sequence_numbers = extract_sequence_number_from_sorted_file(input_csv)

    data_transformed = []

    with open(input_csv, 'r') as csv_file:
        csv_reader = csv.DictReader(csv_file)

        for row in csv_reader:
            transformed_row = {}

            for field, rule in processing_rules.items():
                if field in row:
                    if rule['type'] == 'sequence':
                        transformed_row[field] = next((seq_num for seq_num in reversed(sequence_numbers) if seq_num >= int(row[field])), None)
                    elif rule['type'] == 'hash':
                        transformed_row[field] = compute_file_md5(row[field])
                    else:
                        raise ValueError(""Invalid processing rule type"")

            data_transformed.append(transformed_row)

    with open(output_json, 'w') as json_file:
        json.dump(data_transformed, json_file)

# Example usage
input_csv_path = ""example.csv""
output_json_path = ""example_output.json""
processing_rules_dict = {
    ""id"": {""type"": ""sequence""},
    ""data"": {""type"": ""hash""}
}

process_data(input_csv_path, output_json_path, processing_rules_dict)
