# Convert CSV",120,,"['```python
import csv
import json
import multiprocessing
from functools import partial

def convert_csv_to_json(csv_file, json_file, output_format='json', columns=None):
    # Check if CSV file exists
    try:
        with open(csv_file, 'r') as file:
            pass
    except FileNotFoundError:
        raise FileNotFoundError(f'CSV file ""{csv_file}"" not found')

    # Check if output format is valid
    if output_format not in ['json', 'html', 'xml']:
        raise ValueError(f'Invalid output format: {output_format}')

    # Initialize dictionary for CSV header to JSON key mapping
    csv_header_to_json_key = {}

    # Define generator for CSV data chunks (for large datasets)
    def csv_data_generator(chunk_size=1000):
        reader = csv.reader(open(csv_file, 'r'), delimiter=',')
        chunk = []
        for row in reader:
            chunk.append(row)
            if len(chunk) == chunk_size:
                yield chunk[1:]  # Skip header row and yield the rest of the chunk rows
                del chunk[:chunk_size]  # Clear the first chunk_size rows to make room for the next one

        if len(chunk) > 0:
            yield chunk[1:]

    # Process CSV data in parallel using multiple CPU cores (if available)
    pool = multiprocessing.Pool()

    results = {}

    def process_data(chunk):
        nonlocal results

        with multiprocessing.Manager() as manager:
            shared_results = manager.dict()

            def _process_row(row):
                nonlocal shared_results

                processed_row = {}

                for i, cell in enumerate(row):
                    if columns and i >= len(columns):
                        continue

                    json_key = csv_header_to_json_key.get(i) or f'col_{i}'

                    if isinstance(cell, str) and '<' in cell or '>' in cell or '&' in cell:
                        processed_row[json_key] = _sanitize_html(cell)
                    else:
                        processed_row[json_key] = cell

                shared_results[cell] = processed_row

            pool.map(_process_row, chunk)

            results.update(shared_results)


    process_data_generator = partial(process_data, chunk_size=500)

    pool.map(process_data_generator, csv_data_generator())



def _sanitize_html(text):
    text.replace(""<"", ""&lt

