import jwt
from datetime import datetime

def validate_and_process_jwt(encoded_token, public_key):
    try:
        # Step 1: Decode the JWT into its three parts
        header, payload, signature = encoded_token.split('.')

        # Step 2: Verify the signature using the provided public key
        decoded_payload = jwt.decode(encoded_token, public_key, algorithms=[""RS256""])

        # Step 3 and 4: Parse the payload and check required fields
        required_fields = [""iss"", ""sub"", ""aud"", ""exp""]
        missing_required_fields = [field for field in required_fields if field not in decoded_payload]

        if missing_required_fields:
            return {
                'valid': False,
                'error': f""Missing required fields: {', '.join(missing_required_fields)}""
            }

        # Step 5: Validate the exp and nbf fields
        current_time = datetime.utcnow()
        if decoded_payload[""exp""] < current_time.timestamp():
            return {'valid': False, 'error': ""Token has expired""}

        if ""nbf"" in decoded_payload and decoded_payload[""nbf""] > current_time.timestamp():
            return {'valid': False, 'error': ""Token is not yet valid""}

        # Step 6: Extract optional fields
        additional_fields = {}
        for field in [""iat""]:
            if field in decoded_payload:
                additional_fields[field] = decoded_payload[field]

        # Step 7: Calculate useful information
        remaining_time = None
        if ""exp"" in decoded_payload:
            remaining_time = datetime.fromtimestamp(decoded_payload[""exp""]) - current_time

        has_passed_nbf = False
        if ""nbf"" in decoded_payload and decoded_payload[""nbf""] <= current_time.timestamp():
            has_passed_nbf = True

        # Step 8: Return the processed data
        return {
            'valid': True,
            'payload': decoded_payload,
            'remaining_time': remaining_time,
            'has_passed_nbf': has_passed_nbf,
            **additional_fields
        }

    except jwt.ExpiredSignatureError:
        return {'valid': False, 'error': ""Token has expired""}
    except jwt.InvalidTokenError:
        return {'valid': False, 'error': ""Invalid token signature""}

# Example usage:
public_key = """"""-----BEGIN PUBLIC KEY-----
MIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEA7x...
-----END PUBLIC KEY-----""""""
encoded_token = ""eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...""
result = validate_and_process_jwt(encoded_token, public_key)
print(result)
