0,"Create a function `load_database` that loads a database from a specified file path. Read the file, parse records into `Record` structs, and store them in an internal data structure. Each `Record` struct should contain fields such as ID, name, and date. Implement error handling to manage cases where the file is missing or has an invalid format. Also, include a function `get_record_count` that returns the total number of records in the loaded database.",121,,"['```go
package main

import (
	""encoding/csv""
	""errors""
	""fmt""
	""os""
)

type Record struct {
	ID   int
	Name string
	Date string
}

type Database struct {
	records []Record
}

func (db *Database) load_database(filePath string) error {
	file, err := os.Open(filePath)
	if err != nil {
		return errors.New(""Failed to open file: "" + err.Error())
	}
	defer file.Close()

	reader := csv.NewReader(file)
	records, err := reader.ReadAll()
	if err != nil {
		return errors.New(""Failed to read file: "" + err.Error())
	}

	db.records = make([]Record, len(records)-1) // Skip header row
	for i, record := range records[1:] {
		ID, _ := strconv.Atoi(record[0])
		db.records[i] = Record{
			ID:   ID,
			Name: record[1],
			Date: record[2],
		}
	}

	return nil
}

func (db *Database) get_record_count() int {
	return len(db.records)
}

func main() {
	db := &Database{}
	err := db.load_database(""path/to/database.csv"")
	if err != nil {
		fmt.Println(""Error:"", err)
		return
	}

	fmt.Println(""Total records:"", db.get_record_count())
}
