class Dinosaur:
    def __init__(self, name, classification, predators):
        self.name = name
        self.classification = classification
        self.predators = predators

def get_dinosaur_details(dino_obj):
    if not isinstance(dino_obj, Dinosaur) or not hasattr(dino_obj, 'predators'):
        return ""Invalid input: Not a valid Dinosaur object with predators attribute.""

    predator_dict = {
        ""Tyrannosaurus Rex"": {""name"": ""Tyrannosaurus Rex"", ""classification"": ""Carnivore""},
        ""Velociraptor"": {""name"": ""Velociraptor"", ""classification"": ""Carnivore""},
        ""Stegosaurus"": {""name"": ""Stegosaurus"", ""classification"": ""Herbivore""},
        # Add more predator types and classifications as needed
    }

    if not dino_obj.predators:
        return f""{dino_obj.name} has no predators.""

    valid_predators = [predator for predator in dino_obj.predators if predator in predator_dict]
    unique_predators = sorted(set(valid_predators))

    predator_details = []
    for predator in unique_predators:
        predator_info = predator_dict[predator]
        predator_details.append(f""{predator} - {predator_info['classification']}"")

    return ""\n"".join(predator_details)

# Example usage
dino_objects = [
    Dinosaur(""Tyrannosaurus Rex"", ""Carnivore"", [""Velociraptor""]),
    Dinosaur(""Stegosaurus"", ""Herbivore"", []),
    Dinosaur(""Allosaurus"", ""Carnivore"", [""Stegosaurus"", ""Triceratops""])
]

for dino in dino_objects:
    print(get_dinosaur_details(dino))

print(get_dinosaur_details(None))  # Invalid input
print(get_dinosaur_details(Dinosaur(""Triceratops"", ""Herbivore"", [""Allosaurus""])))  # Valid input
print(get_dinosaur_details(Dinosaur(""Triceratops"", ""Herbivore"", [""Dilophosaurus""])))  # No valid predator
