0,"Design and implement a new API task that involves creating, reading, updating, and deleting (CRUD) operations for a list of products in an e-commerce application. The task should include functions for creating a new product, retrieving a specific product, updating an existing product's details, and deleting a product from the database. Ensure error handling is incorporated to manage failures during these operations. Additionally, demonstrate the usage of these functions with example calls that showcase creating a new product, retrieving its details, updating the product's price and stock quantity, and finally deleting the product from the list.",352,,"['```python
# Define a class to represent a Product
class Product:
    def __init__(self, id, name, price, stock):
        self.id = id
        self.name = name
        self.price = price
        self.stock = stock

    def update_price(self, new_price):
        self.price = new_price

    def update_stock(self, new_stock):
        self.stock = new_stock

# Define a class to manage the product database
class ProductManager:
    def __init__(self):
        self.products = {}

    # Create a new product and add it to the database
    def create_product(self, id, name, price, stock):
        if id in self.products:
            raise ValueError(""Product ID already exists"")
        product = Product(id, name, price, stock)
        self.products[id] = product

    # Retrieve a specific product by its ID
    def get_product(self, id):
        if id not in self.products:
            raise KeyError(""Product not found"")
        return self.products[id]

    # Update an existing product's details
    def update_product(self, id, name=None, price=None, stock=None):
        if id not in self.products:
            raise KeyError(""Product not found"")
        product = self.products[id]
        if name is not None:
            product.name = name
        if price is not None:
            product.update_price(price)
        if stock is not None:
            product.update_stock(stock)

    # Delete a product from the database
    def delete_product(self, id):
        if id not in self.products:
            raise KeyError(""Product not found"")
        del self.products[id]

# Example usage
def main():
    manager = ProductManager()

    # Create a new product
    try:
        manager.create_product(1, ""Laptop"", 999.99, 50)
        print(""Product created successfully."")
    except ValueError as e:
        print(e)

    # Retrieve the product details
    try:
        product = manager.get_product(1)
        print(f""Product ID: {product.id}, Name: {product.name}, Price: ${product.price}, Stock: {product.stock}"")
    except KeyError as e:
        print(e)

    # Update the product's price and stock
    try:
        manager.update_product(1, price=1099.99, stock=30)
        print(""Product updated successfully."")
    except KeyError as e:
        print(e)

    # Delete the product
    try:
        manager.delete_product(1)
        print(""Product deleted successfully."")
    except KeyError as e:
        print(e)

if __name__ == ""__main__"":
    main()
