import requests
from bs4 import BeautifulSoup
from concurrent.futures import ThreadPoolExecutor, as_completed
import re
import time

# Define a function to fetch URLs concurrently using multithreading
def fetch_url(url):
    try:
        response = requests.get(url)
        if response.status_code == 200:
            return url, response.text
        else:
            return url, None
    except requests.RequestException as e:
        print(f""Error fetching {url}: {e}"")
        return url, None

# Define a function to parse HTML and extract links
def parse_html(url, html_content):
    soup = BeautifulSoup(html_content, 'html.parser')
    links = {}
    for a_tag in soup.find_all('a', href=True):
        link_url = re.sub(r'\s+', '', a_tag['href'].lower())
        if not link_url.startswith('#'):
            links[link_url] = a_tag.get_text(strip=True)
    return url, links

# Define the main function to perform recursive crawling
def crawl_links(url, depth=1, max_depth=3, cache=None):
    if depth > max_depth:
        return {}

    if cache and url in cache:
        print(f""Using cached content for {url}"")
        html_content = cache[url]
    else:
        print(f""Fetching URL: {url}"")
        response = requests.get(url)
        html_content = response.text
        if cache:
            cache[url] = html_content

    urls = parse_html(url, html_content)[1]

    result = {}
    with ThreadPoolExecutor(max_workers=5) as executor:
        future_to_url = {executor.submit(fetch_url, link): link for link in urls.keys()}
        for future in as_completed(future_to_url):
            link = future_to_url[future]
            try:
                sub_url, sub_html_content = future.result()
                if sub_html_content:
                    result[sub_url] = parse_html(sub_url, sub_html_content)[1]
                    if depth < max_depth:
                        result.update(crawl_links(sub_url, depth + 1, max_depth, cache))
            except Exception as e:
                print(f""Error processing {link}: {e}"")

    return result

# Example usage
url = 'https://example.com'
result = crawl_links(url)
print(result)
```

