import json

class JsonClass:
    registry = {}

    @staticmethod
    def create_json_instance(data):
        return json.dumps(data)

    @classmethod
    def add_factory_function(cls, id, factory_func):
        cls.registry[id] = factory_func

    @classmethod
    def create_instance_from_id(cls, id, *args, **kwargs):
        if id in cls.registry:
            factory_func = cls.registry[id]
            return factory_func(*args, **kwargs)
        else:
            raise ValueError(f""No factory function registered for ID: {id}"")

# Example usage:
class CustomSubClass(JsonClass):
    def __init__(self, name, age):
        self.name = name
        self.age = age

def custom_factory(name, age):
    return CustomSubClass(name, age)

JsonClass.add_factory_function('custom_id', custom_factory)

# Creating an instance using the factory function from ID
instance = JsonClass.create_instance_from_id('custom_id', 'John', 30)
print(instance.name)  # Output: John
print(instance.age)   # Output: 30
```']",0,[0],[],True,0,0,0,

