class Record:
    def __init__(self, value):
        self.value = value

def generate_records(num_records):
    records = []
    offsets = [random.randint(1, 1000) for _ in range(num_records)]
    keys = [random.randint(1, 100) for _ in range(num_records)]

    for i in range(num_records):
        record = Record(random.randint(1, 100))
        records.append(record)

    return records, offsets, keys

def compute_md5_hash(record):
    content_path = f""content{record.value}.txt""

    with open(content_path, 'rb') as file:
        chunk_size = 65536
        file.seek(offsets[i])
        md5_hasher = hashlib.md5()
        file_data = file.read(chunk_size)

        while len(file_data) > 0:
            md5_hasher.update(file_data)
            file_data = file.read(chunk_size)

    return md5_hasher.hexdigest()

def process_files(records, offsets, keys):
    hashes_of_records_content = {}

    for i in range(len(records)):
        record_md5_hash = compute_md5_hash(records[i])
        hashes_of_records_content[keys[i]] = (offsets[i], record_md5_hash)

    return hashes_of_records_content

# Main function to execute the enhanced coding task
