import random
import hashlib
import os
import threading

class Record:
    def __init__(self, value):
        self.value = value

def generate_records(num_records):
    records = []
    offsets = [random.randint(1, 1000) for _ in range(num_records)]
    keys = [random.randint(1, 100) for _ in range(num_records)]

    for i in range(num_records):
        record = Record(random.randint(1, 100))
        records.append(record)

    return records, offsets, keys

def compute_md5_hash(record):
    content_path = f""content{record.value}.txt""

    with open(content_path, 'rb') as file:
        chunk_size = 65536
        file.seek(offsets[i])
        md5_hasher = hashlib.md5()

        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break
            md5_hasher.update(chunk)

    return md5_hasher.hexdigest()

def process_files(records, offsets, keys):
    hashes_of_records_content = {}

    for i in range(len(records)):
        record_md5_hash = compute_md5_hash(records[i])
        hashes_of_records_content[keys[i]] = (offsets[i], record_md5_hash)

    return hashes_of_records_content

def fetch_file_content(record):
    content_path = f""content{record.value}.txt""

    if os.path.exists(content_path):
        with open(content_path, 'r') as file:
            return file.read()

def create_or_fetch_file_content(records):
    threads = []

    for record in records:
        thread = threading.Thread(target=fetch_file_content, args=(record,))
        threads.append(thread)

        thread.start()

    for thread in threads:
        thread.join()

def process_with_multithreading(records_list, offsets_list, keys_list):
    computed_hashes_dict_multithreaded = {}

    create_or_fetch_file_content(records_list)

    for i in range(len(records_list)):
        record_md5_hash_multithreaded = compute_md5_hash(records_list[i])

        computed_hashes_dict_multithreaded[keys_list[i]] = (offsets_list[i], record_md5_hash_multithreaded)

