class CatalogManager:
    def __init__(self):
        self.albums = []
        self.default_sort_key = ""release_year""
        self.albums_per_page = 10

    def add_album(self, title, artist, genre, release_year):
        if not all([title, artist, genre, isinstance(release_year, int)]):
            raise ValueError(""Invalid data provided"")
        album = {""title"": title, ""artist"": artist, ""genre"": genre, ""release_year"": release_year}
        self.albums.append(album)

    def remove_album(self, title):
        try:
            self.albums.remove(next(filter(lambda x: x[""title""] == title, self.albums)))
        except StopIteration:
            raise ValueError(""Album not found"")

    def sort_catalog(self, key=None):
        if key is None:
            key = self.default_sort_key
        self.albums.sort(key=lambda x: x[key])

    def search_albums(self, keyword, by=""title""):
        return list(filter(lambda x: keyword.lower() in x[by].lower(), self.albums))

    def calculate_total_sales_value(self):
        total_value = 0
        for album in self.albums:
            # Assuming each album has a 'price' and 'sales' attribute
            if ""price"" in album and ""sales"" in album:
                total_value += album[""price""] * album[""sales""]
        return total_value

    def set_default_sort_key(self, key):
        if key in [""title"", ""artist"", ""genre"", ""release_year""]:
            self.default_sort_key = key
        else:
            raise ValueError(""Invalid sort key"")

    def set_albums_per_page(self, count):
        if isinstance(count, int) and count > 0:
            self.albums_per_page = count
        else:
            raise ValueError(""Invalid number of albums per page"")

