import random
import time

def measure_time(func, *args):
    runs = random.randint(1, 10)
    total_time = 0
    for _ in range(runs):
        start_time = time.time()
        func(*args)
        end_time = time.time()
        total_time += (end_time - start_time)
    average_time = total_time / runs
    print(f""Average execution time: {average_time:.6f} seconds"")

def process_data(data):
    if isinstance(data[0], int):
        return sum(data)  # Summing integers for complexity
    else:
        return len(data)  # Counting strings for complexity

if __name__ == ""__main__"":
    data = [random.randint(1, 1000) for _ in range(1000)]  # Generate a list of random numbers
    measure_time(process_data, data)
