import random
import hashlib

class Record:
    def __init__(self, attr1, attr2):
        self.attr1 = attr1
        self.attr2 = attr2

def generate_records(num_records):
    records = []
    offset_array = [random.randint(0, 100) for _ in range(num_records)]
    key_array = [random.randint(0, 256) for _ in range(num_records)]

    for i in range(num_records):
        record = Record(random.randint(0, 1000), random.randint(0, 1000))
        records.append(record)
        hash_object = hashlib.md5(f""{record.attr1}{record.attr2}"".encode())
        print(f""Record {i} MD5: {hash_object.hexdigest()}"")

    return records, offset_array, key_array
