Implement unit tests for each function in isolation and as part of the entire process to guarantee correctness.",680,,"['Certainly! Below is a structured Python implementation following your specifications:

```python
import hashlib
import random
import string

class MAC_APN_SELECTION_REQUEST:
    def __init__(self, apn_name, ue_id, authenticator):
        self.apn_name = apn_name
        self.ue_id = ue_id
        self.authenticator = authenticator

def generate_authenticator(ue_id):
    return hashlib.sha256(ue_id.encode()).hexdigest()

def is_valid_ue_id(ue_id):
    return all(c in string.hexdigits for c in ue_id) and len(ue_id) == 16

def create_mac_apn_selection_request(apn_name, ue_id):
    if not is_valid_ue_id(ue_id):
        raise ValueError(""Invalid UE_ID"")

    authenticator = generate_authenticator(ue_id)
    return MAC_APN_SELECTION_REQUEST(apn_name, ue_id, authenticator)

def test_generate_authenticator():
    test_cases = [
        (""test"", ""0123456789abcdef""),
        (""another_test"", ""abcd1234efgh5678"")
    ]

    for _, ue_id in test_cases:
        assert len(generate_authenticator(ue_id)) == 64

def test_create_mac_apn_selection_request():
    apn_name = ""internet""
    valid_ue_id = ""0123456789abcdef""
    invalid_ue_id = ""not_a_valid_hex_id""

    # Test with a valid UE_ID
    mac_req = create_mac_apn_selection_request(apn_name, valid_ue_id)
    assert isinstance(mac_req, MAC_APN_SELECTION_REQUEST)
    assert mac_req.apn_name == apn_name
    assert mac_req.ue_id == valid_ue_id
    assert len(mac_req.authenticator) == 64

    # Test with an invalid UE_ID
    try:
        create_mac_apn_selection_request(apn_name, invalid_ue_id)
    except ValueError as e:
        assert str(e) == ""Invalid UE_ID""

if __name__ == ""__main__"":
    test_generate_authenticator()
    test_create_mac_apn_selection_request()
```

