This merged system not only demonstrates an integration of different functionalities but also showcases how Python can be utilized effectively for data manipulation tasks involving both random data generation and cryptographic hashing within various applications such as data integrity checks or secure storage solutions.",200,,"['```python
import os
import hashlib
import random

class Record:
    def __init__(self, binary_flag, rnt):
        self.binary_flag = binary_flag
        self.rnt = rnt

def generate_records(num_records, offset_range, key_length):
    records = []
    for _ in range(num_records):
        binary_flag = random.choice([0, 1])
        rnt = random.randint(0, 2**32 - 1)
        record = Record(binary_flag, rnt)
        records.append(record)

        # Generate temporary text file
        temp_file_path = f""temp_record_{record.rnt}.txt""
        with open(temp_file_path, 'w') as file:
            file.write(f""{binary_flag}:{rnt}"")

    return records

def compute_md5_hash(file_path, offset):
    hash_object = hashlib.md5()
    with open(file_path, 'rb') as file:
        file.seek(offset)
        while True:
            data = file.read(4096)  # Read in chunks
            if not data:
                break
            hash_object.update(data)
    return hash_object.hexdigest()

def process_files(records):
    key_to_hash_info = {}
    for record in records:
        file_path = f""temp_record_{record.rnt}.txt""
        offset = random.randint(0, 1024)  # Example offset
        md5_hash = compute_md5_hash(file_path, offset)

        if record.rnt not in key_to_hash_info:
            key_to_hash_info[record.rnt] = []
        key_to_hash_info[record.rnt].append((offset, md5_hash))

    for file_path in os.listdir('.'):
        if file_path.startswith('temp_record_'):
            os.remove(file_path)

    return key_to_hash_info

def main():
    num_records = 10
    offset_range = (0, 4096)
    key_length = 8

    records = generate_records(num_records, offset_range, key_length)
    result_dict = process_files(records)

    print(result_dict)

if __name__ == ""__main__"":
    main()
