import os

# Data generation for enhanced complexity
def generate_data(num_rows, num_columns):
    np.random.seed(0)
    return pd.DataFrame(np.random.randint(0, 100, size=(num_rows, num_columns)), columns=[f'Column_{i}' for i in range(1, num_columns+1)])

# Enhanced function to read data from CSV or generate synthetic data
def load_data(file_path='data.csv', generate=False):
    if generate:
        data = generate_data(1000, 5)
        data.to_csv(file_path, index=False)
        return pd.read_csv(file_path)
    else:
        return pd.read_csv(file_path)

# Statistical analysis using Pandas and NumPy functions
def perform_analysis(data):
    summary_stats = {
        'mean': data.mean(),
        'median': data.median(),
        'std_dev': data.std(),
        'min': data.min(),
        'max': data.max()
    }

    # Custom analysis function: correlation matrix between all columns
    correlation_matrix = np.corrcoef(data.T)

    return summary_stats, correlation_matrix

# Enhanced output to JSON with additional details and formatting
def output_to_json(results):
    json_output = {
        'summary_statistics': results[0],
        'correlation_matrix': results[1].tolist(),
        'file_used': file_path,
        'analysis_date': datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    }

    with open('output.json', 'w') as f:
        json.dump(json_output, f, indent=4)

# Main script with user interaction and error handling
