0,"Create a program that reads a file containing employee records, calculates the average salary for employees in each department, and outputs the results in a CSV format. Each record in the input file should include an employee ID, name, department, and salary. The program should first parse the input file to extract this information, then group the records by department to calculate the average salary for each department. Finally, it should write these averages to an output CSV file with columns for department name and average salary.",680,,"['```python
import csv

def read_employee_records(file_path):
    employees = []
    with open(file_path, 'r') as file:
        reader = csv.DictReader(file)
        for row in reader:
            employee = {
                'id': row['Employee ID'],
                'name': row['Name'],
                'department': row['Department'],
                'salary': float(row['Salary'])
            }
            employees.append(employee)
    return employees

def calculate_average_salaries(employees):
    department_salaries = {}
    for employee in employees:
        department = employee['department']
        salary = employee['salary']

        if department not in department_salaries:
            department_salaries[department] = {'total': 0, 'count': 0}

        department_salaries[department]['total'] += salary
        department_salaries[department]['count'] += 1

    average_salaries = {dept: total / count for dept, total_count in department_salaries.items()}
    return average_salaries

def write_average_salaries_to_csv(average_salaries, output_file_path):
    with open(output_file_path, 'w', newline='') as file:
        writer = csv.writer(file)
        writer.writerow(['Department', 'Average Salary'])

        for dept, avg_salary in average_salaries.items():
            writer.writerow([dept, avg_salary])

def main(input_file_path, output_file_path):
    employees = read_employee_records(input_file_path)
    average_salaries = calculate_average_salaries(employees)
    write_average_salaries_to_csv(average_salaries, output_file_path)

if __name__ == ""__main__"":
    input_path = 'employee_records.csv'
    output_path = 'department_averages.csv'
