import os
import json
import fs

def file_traversal_and_serialization(directory_path, file_extension):
    file_dict = {}
    try:
        for root, dirs, files in os.walk(directory_path):
            for name in files:
                if name.endswith(file_extension) and not name.startswith('.'):
                    file_path = os.path.join(root, name)
                    try:
                        with fs.open(file_path) as f:
                            file_content = f.read().decode('utf-8')
                            file_dict[file_path] = file_content
                    except Exception as e:
                        print(f""Error reading {file_path}: {e}"")
        return json.dumps(file_dict)
    except Exception as e:
        print(f""An error occurred during directory traversal: {e}"")
        return None

# Usage example with '.pdf' extension and 'C:/example'
directory_path = ""C:/example""
file_extension = "".pdf""
