# Function to fetch data from an external API
def fetch_data(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        logging.error(f""Error fetching data: {e}"")
        raise

# Route to predict outcomes using the trained model
@app.route('/predict', methods=['POST'])
def predict():
    try:
        data = request.get_json(force=True)
        features = data['features']

        if not all(isinstance(f, (int, float)) for f in features):
            return jsonify({""error"": ""Invalid data type""}), 400

        prediction = model.predict([features])
        reliability_score = model.predict_proba([features])[0][prediction[0]]

        return jsonify({
            ""prediction"": int(prediction[0]),
            ""reliability_score"": float(reliability_score)
        }), 200
    except KeyError as e:
        logging.error(f""Missing key in data: {e}"")
        return jsonify({""error"": ""Missing required field""}), 400
    except Exception as e:
        logging.error(f""Unexpected error during prediction: {e}"")
        return jsonify({""error"": ""Internal server error""}), 500

# Route to load a pre-trained model
@app.route('/load_model', methods=['POST'])
def load_model():
    try:
        # Assuming the model is loaded from a secure storage mechanism like S3
        global model
        model = RandomForestClassifier()  # Load your model here
        return jsonify({""message"": ""Model loaded successfully""}), 200
    except Exception as e:
        logging.error(f""Error loading model: {e}"")
        return jsonify({""error"": ""Failed to load model""}), 500

if __name__ == '__main__':
    app.run(debug=True)
