0,"Create `load_database` function to read a file at a given path, parse records into `Record` structs (ID, name, date), store them internally, and handle missing or invalid file errors. Also, implement `get_record_count` to return the total number of records in the loaded database.",121,,"['```go
package main

import (
	""encoding/csv""
	""errors""
	""os""
	""strconv""
	""time""
)

type Record struct {
	ID    int       `json:""id""`
	Name  string    `json:""name""`
	Date  time.Time `json:""date""`
}

type Database struct {
	records []Record
}

func (db *Database) load_database(filePath string) error {
	file, err := os.Open(filePath)
	if err != nil {
		return err
	}
	defer file.Close()

	reader := csv.NewReader(file)
	records, err := reader.ReadAll()
	if err != nil {
		return err
	}

	db.records = make([]Record, 0, len(records))
	for _, record := range records[1:] { // Skip header
		id, _ := strconv.Atoi(record[0])
		date, err := time.Parse(""2006-01-02"", record[2])
		if err != nil {
			return errors.New(""invalid date format"")
		}
		db.records = append(db.records, Record{ID: id, Name: record[1], Date: date})
	}

	return nil
}

func (db *Database) get_record_count() int {
	return len(db.records)
}

func main() {
	db := &Database{}
	err := db.load_database(""data.csv"")
	if err != nil {
		panic(err)
	}
	fmt.Println(""Total records:"", db.get_record_count())
}
```']",0,[0],[],True,0,0,0,

