# Python script to generate random geometric shapes for testing purposes

import json
import random
from PIL import Image, ImageDraw

def generate_shapes(num_shapes):
    shapes = []
    for _ in range(num_shapes):
        shape_type = random.choice(['rectangle', 'circle', 'ellipse'])
        x, y = random.randint(0, 512), random.randint(0, 512)
        width, height = random.randint(30, 200), random.randint(30, 200)
        color = (random.randint(0, 255), random.randint(0, 255), random.randint(0, 255))
        rotation_angle = random.randint(0, 360)
        shapes.append({
            'type': shape_type,
            'x': x,
            'y': y,
            'width': width,
            'height': height,
            'color': color,
            'rotation_angle': rotation_angle
        })
    return shapes

def save_shapes_to_file(shapes, filename):
    with open(filename, 'w') as f:
        json.dump(shapes, f)

if __name__ == ""__main__"":
    num_shapes = 1000
    shapes = generate_shapes(num_shapes)
    save_shapes_to_file(shapes, 'shapes_dataset.json')
