import sqlite3

class DatabaseManager:
    def __init__(self, db_name):
        self.connection = None
        self.db_name = db_name
        try:
            self.connect()
        except Exception as e:
            print(f""Failed to connect to the database: {e}"")

    def connect(self):
        self.connection = sqlite3.connect(self.db_name)
        cursor = self.connection.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                email TEXT NOT NULL UNIQUE
            )
        ''')
        self.connection.commit()

    def insert_data(self, name, email):
        if not self.validateData(name, email):
            return ""Invalid data provided""
        try:
            cursor = self.connection.cursor()
            cursor.execute(""INSERT INTO users (name, email) VALUES (?, ?)"", (name, email))
            self.connection.commit()
            return ""Data inserted successfully""
        except Exception as e:
            return f""Failed to insert data: {e}""

    def retrieve_data(self):
        try:
            cursor = self.connection.cursor()
            cursor.execute(""SELECT * FROM users"")
            return cursor.fetchall()
        except Exception as e:
            return f""Failed to retrieve data: {e}""

    def update_data(self, user_id, name, email):
        if not self.validateData(name, email):
            return ""Invalid data provided""
        try:
            cursor = self.connection.cursor()
            cursor.execute(""UPDATE users SET name = ?, email = ? WHERE id = ?"", (name, email, user_id))
            self.connection.commit()
            return ""Data updated successfully""
        except Exception as e:
            return f""Failed to update data: {e}""

    def delete_data(self, user_id):
        try:
            cursor = self.connection.cursor()
            cursor.execute(""DELETE FROM users WHERE id = ?"", (user_id,))
            self.connection.commit()
            return ""Data deleted successfully""
        except Exception as e:
            return f""Failed to delete data: {e}""

    def validateData(self, name, email):
        if not name or not email:
            return False
        if '@' not in email:
            return False
        return True

def captureInput():
    while True:
        name = input(""Enter your name (or type 'exit' to quit): "")
        if name.lower() == 'exit':
            break
        email = input(""Enter your email: "")
        validation_result = validateData(name, email)
        if validation_result:
            return name, email
        else:
            print(""Invalid input. Please try again."")

def validateData(name, email):
    db_manager = DatabaseManager('users.db')
    return db_manager.validateData(name, email)

if __name__ == ""__main__"":
    while True:
        action = input(""Choose an action (insert, retrieve, update, delete, exit): "")
        if action.lower() == 'exit':
            break
        elif action.lower() == 'insert':
            name, email = captureInput()
            db_manager = DatabaseManager('users.db')
            result = db_manager.insert_data(name, email)
            print(result)
        elif action.lower() == 'retrieve':
            db_manager = DatabaseManager('users.db')
            users = db_manager.retrieve_data()
            for user in users:
                print(user)
        elif action.lower() == 'update':
            try:
                user_id = int(input(""Enter the ID of the user to update: ""))
                name, email = captureInput()
                db_manager = DatabaseManager('users.db')
                result = db_manager.update_data(user_id, name, email)
                print(result)
            except ValueError:
                print(""Invalid ID. Please enter a valid integer."")
        elif action.lower() == 'delete':
            try:
                user_id = int(input(""Enter the ID of the user to delete: ""))
                db_manager = DatabaseManager('users.db')
                result = db_manager.delete_data(user_id)
                print(result)
            except ValueError:
                print(""Invalid ID. Please enter a valid integer."")
        else:
            print(""Invalid action. Please choose from insert, retrieve, update, delete, or exit."")
