import java.security.MessageDigest
import java.security.NoSuchAlgorithmException

def hashSecret(secret):
    try:
        digest = MessageDigest.getInstance(""MD5"")
        encodedBytes = digest.digest(secret.getBytes())
        hexString = new StringBuilder()
        for b in encodedBytes:
            hex = Integer.toHexString(0xff & b)
            if len(hex) == 1: hexString.append('0')
            hexString.append(hex)
        return hexString.toString()
    except NoSuchAlgorithmException as e:
        raise RuntimeException(""Error hashing secret"", e)

# Hashing the secrets from Python instances in Java
