import os
from hashlib import md5

class UserDefinedData:
    def __init__(self):
        self.id = id(self)
        self.secret = ''.join(os.urandom(10)).encode('utf-8')

    @staticmethod
    def hash_secret(secret):
        hashed_bytes = md5(secret).digest()
        return ''.join(f'{byte:02x}' for byte in hashed_bytes)

def generate_data_instances(num_instances):
    instances = []
    for _ in range(num_instances):
        instance = UserDefinedData()
        encoded_message = instance.secret.decode('utf-8')
        instances.append((instance.id, instance.secret, encoded_message))
    return instances
