import hashlib
import os

class UserDefinedData:
    def __init__(self, user_id):
        self.user_id = user_id
        self.secret = self.generate_secret()
        self.encoded_message = self.encode_message(self.secret)

    @staticmethod
    def generate_secret():
        return ''.join([chr(x) for x in os.urandom(10)])

    @staticmethod
    def encode_message(message):
        return message.encode('utf-8')

def generate_data_instances(num_instances):
    instances = []
    for i in range(num_instances):
        user_id = f""user_{i+1}""
        instance = UserDefinedData(user_id)
        instances.append(instance)
    return instances

# Java method to hash Python-generated secrets using MD5
def hashSecret(secret):
    md5 = hashlib.md5()
    md5.update(secret.encode('utf-8'))
