from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
import os
import hashlib
import concurrent.futures

class UserDefinedData:
    def __init__(self, ID, secret, message, encrypted=False):
        self.ID = ID
        self.secret = secret
        self.message = message
        self.encrypted = encrypted

def generate_random_data():
    try:
        return os.urandom(16)
    except Exception as e:
        raise ValueError(""Failed to generate random data"") from e

def encrypt_message(message, key):
    iv = os.urandom(16)
    cipher = Cipher(algorithms.AES(key), modes.CFB(iv), backend=default_backend())
    encryptor = cipher.encryptor()
    return iv + encryptor.update(message) + encryptor.finalize()

def decrypt_message(encrypted_data, key):
    iv = encrypted_data[:16]
    ciphertext = encrypted_data[16:]
    cipher = Cipher(algorithms.AES(key), modes.CFB(iv), backend=default_backend())
    decryptor = cipher.decryptor()
    return decryptor.update(ciphertext) + decryptor.finalize()

def generate_user_defined_data(N, algorithm='AES', key=None):
    if not key:
        key = os.urandom(32)
    results = []
    with concurrent.futures.ProcessPoolExecutor() as executor:
        futures = [executor.submit(lambda i: UserDefinedData(i, generate_random_data().hex(), encrypt_message(generate_random_data(), key), True) for i in range(N)]
        for future in concurrent.futures.as_completed(futures):
            results.append(future.result())
    return results

def compare_messages_by_checksum(message1, message2):
    return hashlib.md5(message1).digest() == hashlib.md5(message2).digest()
